#!/usr/bin/env node
// Graph runtime for a workflow skill generated by vajra.
//
// Puts the agent on the rails of the graph instead of trusting it to follow prose. The runtime
// keeps the run state (a checkpoint: which playbook owns the request, which steps are done),
// refuses every move the graph does not allow, runs each playbook's checks before its exits open,
// and interrupts at every [human-gate] until the human resumes it. The agent drives it as a CLI (no
// context cost until used), and lifecycle hooks in Claude Code, Codex and GitHub Copilot (JSON on
// stdin, a JSON deny blocks) enforce it whether or not the agent cooperates.
// An MCP server is available as an opt-in for clients that support MCP elicitation.
//
// Agent commands:
//   flow status [--json]
//   flow start <playbook> --request "<one line>" [--abandon "<reason>"]
//   flow step <n> --evidence "<what shows it>"  |  flow step <n> --skip "<reason>"
//   flow finish --evidence "<what proves Done when>"
//   flow exit <to> --because "<why its condition holds>"
//   flow pause --note "<handoff>"  |  flow resume
//   flow log
//   flow request suspend --reason "<what you need to change>"   ask the user to suspend the rails
//   flow request cancel                                         withdraw that request
//   flow unsuspend                                              turn the rails back on
//   flow answer approve|reject|suspend|decline [--note "<why>"]   record the user's answer
// The human answers a [human-gate] or a suspend request as they would anyone: a choice in the
// agent's question dialog, or a reply in their own words. The agent records what they meant with
// `flow answer`, and the rails accept it only once the user has replied since the question was
// asked (see "the user's answers" below). Nothing needs a terminal, though these still
// work in the human's own one (the hooks block the agent from running them):
//   flow approve [--by <name>] [--note <text>]    resume the interrupted [human-gate]
//   flow reject --reason <text>                   refuse it
//   flow suspend                                  turn the hooks off until flow unsuspend
// Integration:
//   flow hook <session-start|user-prompt|pre-tool-use|post-tool-use|stop> [--agent claude|codex|copilot]
//                                                 lifecycle hook (JSON on stdin)
//   flow install --harness <claude|codex|copilot>[,...]
//                [--scope project|local] [--mcp] [--dry-run]
//                                                 hooks, plus a .flow/<skill>/project.md skeleton
//                                                 for the skill's bindings when there is none
//   flow mcp                                      opt-in MCP server over stdio (gates and suspend
//                                                 requests via elicitation)
//
// Exit codes: 0 ok, 1 refused by the graph, 2 usage, 3 interrupted for the human.
// Environment: FLOW_ROOT (project root), FLOW_SKILL (skill directory; default: the parent of scripts/).
// Project values: the skill names commands, paths and other repository-specific values as ${name}
// bindings (declared in its bindings.md); each project gives them in .flow/<skill>/project.md.
// No dependencies: Node 18+ only. The runtime lives in lib/ next to this file; this file is its
// command line and the hooks' entry point, and holds only what must work when lib/ does not load.

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

// The rest of the runtime is loaded here rather than imported, so a missing or outdated file is
// caught and the hook falls back to a plain text check instead of failing (see degradedHook).
const REQUIRED = { "hooks.mjs": ["runHook"], "cli.mjs": ["execute"], "mcp.mjs": ["serveMcp"], "run.mjs": ["approve", "reject"] };
let loadError = null;
const lib = {};
for (const [file, names] of Object.entries(REQUIRED)) {
  try {
    const m = await import(`./lib/${file}`);
    const missing = names.filter((n) => m[n] === undefined);
    if (missing.length) throw new Error(`${file} lacks ${missing.join(", ")}; copy the runtime from vajra again`);
    Object.assign(lib, m);
  } catch (e) { loadError ||= `${file}: ${e.message}`; }
}

// The same as lib/env.mjs, repeated so the way out below never depends on lib/.
const here = path.dirname(fileURLToPath(import.meta.url));
const skillDir = path.resolve(process.env.FLOW_SKILL || path.join(here, ".."));
const skillName = path.basename(skillDir);
const tag = `[${skillName}]`;
const relPath = (root, p) => path.relative(root, p).split(path.sep).join("/");

export function findRoot(start = process.cwd()) {
  if (process.env.FLOW_ROOT) return path.resolve(process.env.FLOW_ROOT);
  if (process.env.CLAUDE_PROJECT_DIR) return path.resolve(process.env.CLAUDE_PROJECT_DIR);
  let d = path.resolve(start);
  for (;;) {
    if (fs.existsSync(path.join(d, ".flow")) || fs.existsSync(path.join(d, ".git"))) return d;
    const up = path.dirname(d);
    if (up === d) return path.resolve(start);
    d = up;
  }
}

// The run state, read and written as lib/store.mjs does, for what must work while lib/ is broken:
// suspending the rails and the degraded hook.
const stateDir = (root) => path.join(root, ".flow", skillName);
function loadState(root) {
  try { return JSON.parse(fs.readFileSync(path.join(stateDir(root), "state.json"), "utf8")); } catch { return { run: null, suspended: false }; }
}
function saveState(root, state, event) {
  const dir = stateDir(root);
  const file = path.join(dir, "state.json");
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(`${file}.tmp`, JSON.stringify(state, null, 2) + "\n");
  fs.renameSync(`${file}.tmp`, file);
  fs.appendFileSync(path.join(dir, "log.jsonl"), JSON.stringify({ at: new Date().toISOString(), ...event }) + "\n");
}

// ---------- the user's answers ----------
// A [human-gate] and a suspend request wait for the user, who answers as they would anyone: a
// choice in the agent's question dialog, or a reply in their own words. The agent records what
// they meant with `flow answer`. The rails do not read the words; they keep every message the user
// sends while a question waits (the prompt hook runs only on the user's prompts, and a choice
// dialog's picks are kept too, see lib/ask.mjs), and accept an answer only once one has come since
// the question was asked, so the agent cannot answer before the user has. What the user sent is
// logged with the answer. This lives here, not in lib/, so a suspend request can be answered while
// lib/ is broken: that is when the user most needs to let the agent repair the skill.
const MAX_HEARD = 20;
function hear(root, texts) {
  const state = loadState(root);
  if (state.suspended || !(state.request || state.run?.awaiting) || !texts.length) return;
  const at = new Date().toISOString();
  state.heard = [...(state.heard || []), ...texts.map((text) => ({ at, text: String(text).slice(0, 20000) }))].slice(-MAX_HEARD);
  saveState(root, state, { event: "heard", count: texts.length });
}
// What the user sent after `since`.
const repliesSince = (state, since) => (state.heard || []).filter((h) => h.at >= since).map((h) => h.text);

// `flow answer approve|reject|suspend|decline [--note <text>]`
function answerCmd(root, verb, o) {
  const state = loadState(root);
  const v = String(verb || "").toLowerCase();
  if (!["approve", "reject", "suspend", "decline"].includes(v)) return { code: 2, text: 'usage: flow answer approve|reject|suspend|decline [--note "<why>"]' };
  const note = typeof o.note === "string" && o.note.trim() ? o.note.trim() : undefined;
  const forGate = v === "approve" || v === "reject";
  const since = forGate ? state.run?.awaiting?.since : state.request?.since;
  if (state.suspended || !since) return { code: 1, text: `${tag} No ${forGate ? "human gate" : "suspend request"} is waiting for an answer.` };
  const said = repliesSince(state, since);
  if (!said.length) return { code: 1, text: `${tag} The user has not replied since you asked, so nothing is recorded. End your turn and wait for their answer.` };
  const heard = said.join("\n").slice(-1000);
  if (!forGate) return { code: 0, text: v === "suspend" ? suspension.grant(root, "the user", note, heard) : suspension.refuse(root, "the user", note, heard) };
  if (loadError) return { code: 1, text: `${tag} the runtime did not load (${loadError}), so the gate cannot be recorded. Tell the user.` };
  const n = (v === "approve" ? lib.approve : lib.reject)(state, "the user", note);
  saveState(root, state, { event: v, run: state.run.id, playbook: state.run.playbook, step: n, by: "user", ...(note ? { note } : {}), heard });
  return { code: 0, text: `${tag} Recorded: the user ${v === "approve" ? "approved" : "rejected"} step ${n}. Tell them so in a line.` };
}

const flowRel = (root) => {
  const rel = relPath(root, path.join(here, "flow.mjs"));
  return `node ${rel.startsWith("..") ? path.join(here, "flow.mjs") : rel}`;
};

export const suspension = {
  // The agent asks; the run waits for the human like a gate (exit code 3).
  request(root, reason) {
    const state = loadState(root);
    if (state.suspended) return { code: 0, text: `${tag} The rails are already suspended. Run \`${flowRel(root)} unsuspend\` when the change is done.` };
    if (typeof reason !== "string" || !reason.trim()) return { code: 2, text: 'usage: flow request suspend --reason "<what you need to change, and why>"' };
    state.request = { action: "suspend", reason: reason.trim(), since: new Date().toISOString() };
    saveState(root, state, { event: "request", action: "suspend", reason: state.request.reason });
    return { code: 3, text: `STOP. Ask the user to suspend the rails so you can ${state.request.reason}.\nWhile they are suspended nothing is enforced: guarded commands run and every file may change, until you run \`${flowRel(root)} unsuspend\`. Tell the user what you will change and ask whether to suspend the rails for it with your tool for putting choices to the user (a dialog or buttons: Suspend / Keep the rails on), in plain words only if you have none, and end your turn. When they answer, record what they meant, however they put it, with \`${flowRel(root)} answer suspend\` or \`${flowRel(root)} answer decline\`. Only the user can allow it, or they run \`flow suspend\` themselves.` };
  },
  cancel(root) {
    const state = loadState(root);
    if (!state.request) return { code: 0, text: `${tag} No suspend request is waiting.` };
    const { reason } = state.request;
    state.request = null;
    saveState(root, state, { event: "cancel-request", reason });
    return { code: 0, text: `${tag} The suspend request is withdrawn.` };
  },
  // The human's answer, recorded by `flow answer` or an elicitation dialog. `by` says which.
  grant(root, by, note, heard) {
    const state = loadState(root);
    const reason = state.request?.reason;
    state.suspended = true;
    state.request = null;
    saveState(root, state, { event: "suspend", by, reason, ...(note ? { note } : {}), ...(heard ? { heard } : {}) });
    return `${tag} The user suspended the rails${reason ? ` so you can ${reason}` : ""}. Do only that, then run \`${flowRel(root)} unsuspend\`.`;
  },
  refuse(root, by, why, heard) {
    const state = loadState(root);
    const reason = state.request?.reason;
    state.request = null;
    saveState(root, state, { event: "reject-request", by, reason, why: why || "no reason given", ...(heard ? { heard } : {}) });
    return `${tag} The user did not suspend the rails${why ? `: ${why}` : ""}. Carry on without changing the workflow's own files.`;
  },
};

// ---------- hook answers, in the fields each agent reads ----------

function context(eventName, text, format) {
  if (format === "antigravity") {
    return JSON.stringify({ injectSteps: [{ systemMessage: { systemMessage: text } }] });
  }
  // hookSpecificOutput.additionalContext is understood by the agents that inject hook context.
  // Copilot CLI reads only a top-level additionalContext; VS Code reads hookSpecificOutput.
  const out = { hookSpecificOutput: { hookEventName: eventName, additionalContext: text } };
  return JSON.stringify(format === "copilot" ? { additionalContext: text, ...out } : out);
}

// A deny in JSON on stdout (exit 0) is read alike by Claude Code, Codex, Copilot and VS Code, and,
// unlike exit code 2, survives PowerShell, which reports any failed native command as exit 1.
function blockTool(reason, format) {
  if (format === "antigravity") {
    console.log(JSON.stringify({ decision: "deny", reason: `${tag} Blocked: ${reason}` }));
    return 0;
  }
  console.log(JSON.stringify({ hookSpecificOutput: { hookEventName: "PreToolUse", permissionDecision: "deny", permissionDecisionReason: `${tag} Blocked: ${reason}` } }));
  return 0;
}

function answer(v, format) {
  if (!v) return 0;
  if (v.deny) return blockTool(v.deny, format);
  if (v.block) console.log(JSON.stringify(format === "antigravity" ? { decision: "continue", reason: `${tag} ${v.block}` } : { decision: "block", reason: `${tag} ${v.block}` }));
  else if (v.context !== undefined) console.log(context(v.event, v.context, format));
  else if (v.unknown !== undefined) console.error(`unknown hook event "${v.unknown}"`);
  return 0;
}

// A hook that crashed (on a payload it does not understand, or with a broken runtime) must not stop
// all work, nor let the rails be changed. It blocks only calls whose text names the workflow's own
// files or the hook settings, which a plain search finds without understanding the call.
const NAMES_RAILS = /\.flow\b|(?:(?<![\w-])|scripts)flow\.mjs|\.claude[\\/]|\.codex[\\/]|\.agents[\\/]|\.github[\\/](hooks|copilot)|\.vscode[\\/]settings|disableAllHooks|useHooks/i;
const METADATA = /^(session|transcript|cwd|permission|hook_?event|timestamp|model|turn)/i;
const NAMES_PROMPT = /\b(claude|codex|copilot)\b|"(prompt|message|text)"\s*:/i;
// The one call that names flow.mjs and still goes through: asking to suspend the rails (or turning
// them back on), written plainly, so the agent can ask the user to let it repair the skill.
const FLOW_PATH = `(?:"[^"\`$]*flow\\.mjs"|'[^']*flow\\.mjs'|[^\\s"'\`$;&|<>()]*flow\\.mjs)`;
const QUOTED = `(?:"[^"\`$\\\\]*"|'[^']*')`;
const ASK_TO_REPAIR = new RegExp(`^\\s*node\\s+${FLOW_PATH}\\s+(?:unsuspend|request\\s+cancel|request\\s+suspend\\s+--reason\\s+${QUOTED}|answer\\s+(?:suspend|decline)(?:\\s+--note\\s+${QUOTED})?)\\s*$`);

function degradedHook(event, e, input, raw, root, format) {
  const state = loadState(root);
  const suspended = state.suspended === true;
  if (event === "pre-tool-use") {
    const ti = input.tool_input && typeof input.tool_input === "object" ? input.tool_input : null;
    const asks = typeof ti?.command === "string" && ASK_TO_REPAIR.test(ti.command);
    // What the call does, without the payload's metadata: Claude Code's transcript_path lies under
    // ~/.claude/, which would make every call look like it names the rails.
    const call = Object.fromEntries(Object.entries(input).filter(([k]) => !METADATA.test(k)));
    const text = Object.keys(input).length ? JSON.stringify(asks ? { ...call, tool_input: { ...ti, command: "" } } : call) : raw;
    const t = text.replace(/\\\\/g, "/");
    const rel = relPath(root, skillDir);
    if (suspended) return 0;
    if (NAMES_RAILS.test(t) || (rel && t.includes(rel))) return blockTool(`the rails could not read this call (${e.message}), and it names the workflow's own files. Stop and ask the user.`, format);
    // While a question waits, a prompt for another agent session, or one scheduled or sent, would
    // arrive as a message from the user and could answer in their place.
    if ((state.request || state.run?.awaiting) && NAMES_PROMPT.test(t)) return blockTool(`the rails could not read this call (${e.message}), and it may hand an agent a prompt that answers in the user's place. Stop and ask the user.`, format);
    return 0;
  }
  if ((event === "session-start" || event === "user-prompt") && !suspended) {
    const degraded = `${tag} The rails are degraded (${e.message}): only calls that name the workflow's own files are blocked. Tell the user, who can copy the runtime from vajra again. To repair it yourself, ${state.request ? `your request to suspend the rails waits for the user: once they have answered, record what they meant with \`${flowRel(root)} answer suspend\` or \`${flowRel(root)} answer decline\`, without asking again` : `run \`${flowRel(root)} request suspend --reason "<what you will repair>"\` and ask the user whether to suspend the rails for it`}.`;
    console.log(context(event === "user-prompt" ? "UserPromptSubmit" : "SessionStart", degraded, format));
  }
  return 0;
}

// ---------- commands ----------

function parseArgs(argv) {
  const pos = [];
  const o = {};
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a.startsWith("--")) {
      const k = a.slice(2);
      const v = argv[i + 1];
      if (v === undefined || v.startsWith("--")) o[k] = true;
      else { o[k] = v; i++; }
    } else pos.push(a);
  }
  return { pos, o };
}

// ---------- main ----------

export function main(argv) {
  const [cmd, ...rest] = argv;
  if (cmd === "hook") {
    const { o } = parseArgs(rest.slice(1));
    const agent = o.agent || (o.format === "copilot" ? "copilot" : undefined); // --format copilot: hooks installed before --agent
    let format = agent === "copilot" ? "copilot" : agent === "antigravity" ? "antigravity" : undefined;
    let raw = "";
    try { raw = fs.readFileSync(0, "utf8"); } catch {}
    let input = {};
    try { input = JSON.parse(raw || "{}"); } catch {}
    if (!input || typeof input !== "object") input = {};
    if (!format && input.conversationId && input.workspacePaths) format = "antigravity";
    const root = findRoot(typeof input.cwd === "string" && input.cwd ? input.cwd : process.cwd());
    // Copilot CLI (and VS Code with chat.useClaudeHooks) also runs the hooks in .claude/settings*.json.
    // Claude Code always sets CLAUDE_PROJECT_DIR and sends no timestamp; Copilot and VS Code do the
    // opposite. A Claude hook run that way answers in Copilot's fields, and steps aside when this
    // skill's hook for the event is in Copilot's own file, which that agent runs as well, so each
    // event runs once. If either sign is missing it runs anyway: twice is better than not at all.
    if (agent === "claude" && !process.env.CLAUDE_PROJECT_DIR) {
      format = "copilot";
      if (input.timestamp !== undefined) {
        let own = "";
        try { own = fs.readFileSync(path.join(root, ".github", "hooks", `${skillName}.json`), "utf8"); } catch {}
        if (own.includes(`hook ${rest[0]} `)) return 0;
      }
    }
    // The user's own message is kept before anything else, so it is there with lib/ broken.
    if (rest[0] === "user-prompt") {
      try {
        const text = String(input.prompt ?? input.user_prompt ?? input.message ?? input.lastUserInput ?? "").trim();
        if (text) {
          const st = loadState(root);
          const waitingSince = st.run?.awaiting?.since || st.request?.since;
          const lastHeard = (st.heard || []).at(-1);
          const isDuplicate = waitingSince && lastHeard && lastHeard.at >= waitingSince && lastHeard.text?.trim() === text;
          if (!isDuplicate) hear(root, [text]);
        }
      } catch {}
    }
    try {
      if (loadError) throw new Error(`the runtime did not load: ${loadError}`);
      // Only Claude Code itself runs Bash in a POSIX shell on Windows; see lib/tools.mjs.
      const v = lib.runHook(rest[0], input, root, { bashIsPosix: agent === "claude" && format !== "copilot" });
      if (v?.heard) { hear(root, v.heard); return 0; }
      if (!v && rest[0] === "pre-tool-use" && format === "antigravity") {
        console.log(JSON.stringify({ decision: "allow" }));
        return 0;
      }
      return answer(v, format);
    } catch (e) {
      return degradedHook(rest[0], e, input, raw, root, format);
    }
  }
  // The way out works even when the runtime or the workflow graph is broken.
  if (cmd === "request") {
    const { pos, o } = parseArgs(rest);
    const root = findRoot();
    const r = pos[0] === "suspend" ? suspension.request(root, o.reason) : pos[0] === "cancel" ? suspension.cancel(root) : { code: 2, text: 'usage: flow request suspend --reason "<what you need to change>"  |  flow request cancel' };
    (r.code === 1 || r.code === 2 ? console.error : console.log)(r.text);
    return r.code;
  }
  if (cmd === "answer") {
    const { pos, o } = parseArgs(rest);
    const r = answerCmd(findRoot(), pos[0], o);
    (r.code === 1 || r.code === 2 ? console.error : console.log)(r.text);
    return r.code;
  }
  if (cmd === "suspend" || cmd === "unsuspend") {
    const root = findRoot();
    const state = loadState(root);
    state.suspended = cmd === "suspend";
    if (state.suspended) state.request = null;
    saveState(root, state, { event: cmd });
    console.log(`${tag} ${state.suspended ? "Rails suspended: the hooks allow everything until flow unsuspend." : "Rails back on."}`);
    return 0;
  }
  if (loadError) { console.error(`${tag} the runtime did not load: ${loadError}`); return 1; }
  if (cmd === "mcp") { lib.serveMcp(findRoot(), suspension); return undefined; }
  if (!cmd || cmd === "help" || cmd === "--help") {
    const lines = fs.readFileSync(fileURLToPath(import.meta.url), "utf8").split("\n");
    console.log(lines.slice(1, lines.findIndex((l, i) => i > 0 && !l.startsWith("//"))).map((l) => l.replace(/^\/\/ ?/, "")).join("\n"));
    return 0;
  }
  const { pos, o } = parseArgs(rest);
  const r = lib.execute(cmd, pos, o, findRoot());
  (r.code === 1 || r.code === 2 ? console.error : console.log)(r.text);
  return r.code;
}

const isMain = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain) {
  const code = main(process.argv.slice(2));
  if (code !== undefined) process.exitCode = code;
}
